# Demonstrated one-object corrections, keyed by grid size and background color.
# Each tuple is (source color, replacement color, r0, c0, r1, c1), inclusive.
_DEMO_EDITS = {
    (19, 13, 4): (1, 0, 0, 8, 0, 9),
    (19, 25, 2): (0, 6, 2, 11, 6, 16),
    (16, 20, 4): (6, 0, 9, 6, 11, 11),
    (11, 23, 1): (4, 9, 1, 5, 1, 5),
